const { randomUUID } = require('crypto');
const userId = $json.userId || 'test-user';
return [{...$json, userId, traceId: `${userId}-${Date.now()}-${randomUUID()}`}];

// Robust routing JSON extraction & normalization to single object
let raw='';
if(typeof $json.text==='string' && $json.text.trim()) raw=$json.text;
else if(typeof $json.message==='string' && $json.message.trim()) raw=$json.message;
else { for (const v of Object.values($json)) { if(typeof v==='string'){ const t=v.trim(); if(t.startsWith('{')||t.startsWith('[')||t.startsWith('```')) { raw=t; break; } } } }
raw=raw.trim();
if(raw.startsWith('```')) { raw=raw.replace(/^```[a-zA-Z0-9]*\s*\n/,''); raw=raw.replace(/```\s*$/,''); }
raw=raw.replace(/^'''[a-zA-Z0-9]*\s*\n/,'').replace(/'''\s*$/,'');
const inner=raw.match(/```[a-zA-Z0-9]*\s*\n([\s\S]*?)\n```/); if(inner) raw=inner[1].trim();
let candidate=raw;
if(!/^\s*(\{[\s\S]*\}|\[[\s\S]*\])\s*$/.test(raw)) { const fb=raw.indexOf('{'); const lb=raw.lastIndexOf('}'); if(fb>=0 && lb>fb) candidate=raw.slice(fb,lb+1); }
let parsed;
try { parsed=JSON.parse(candidate); } catch(e){ parsed={ parseError:e.message, originalSample: raw.slice(0,300) }; }
if(Array.isArray(parsed) && parsed.length===1 && typeof parsed[0]==='object') { parsed=parsed[0]; parsed.unwrappedArray=true; }
if(Array.isArray(parsed) && parsed.length>1) { parsed={ ...parsed[0], droppedItems: parsed.length-1, warning: 'Multiple objects returned; only first used.' }; }
if(!parsed.route) parsed.route='vikunja_specialist';
if(!parsed.intent) parsed.intent='unknown';
return [parsed];

const o = $json;
const allowedRoutes = ['vikunja_specialist','none','calendar_specialist','documents_specialist'];
if(!allowedRoutes.includes(o.route)) o.route='vikunja_specialist';
const allowedIntents = ['complete_task','recommendations','create_task','plan_project','reminder','unknown'];
if(!allowedIntents.includes(o.intent)) o.intent='unknown';
if(typeof o.confidence !== 'number') o.confidence = 1;
if(typeof o.query !== 'string') o.query = ''; else o.query = o.query.trim();
if(typeof o.rawUserMessage !== 'string') o.rawUserMessage = '';
if(typeof o.meta !== 'object' || o.meta===null) o.meta = {};
if(o.meta.selectionIndex != null){ const si = parseInt(o.meta.selectionIndex,10); if(!Number.isNaN(si) && si>0) o.meta.selectionIndex = si; else delete o.meta.selectionIndex; }
return [o];

// Parses user selection messages when multiple_options previously shown
const txt = ($json.rawUserMessage||'').toLowerCase();
const ord = { first:1, second:2, third:3, fourth:4, fifth:5 };
let idx = null;
const m = txt.match(/\b(\d+)\b/);
if (m) idx = +m[1];
else for (const [k,v] of Object.entries(ord)) if (txt.includes(k)) { idx = v; break; }
return [{...$json, selectionIndex: idx}];

const r = $json;
// Prepare user-facing message based on status
let outMsg = r.message || '';
if (r.status === 'multiple_options' && Array.isArray(r.options)) {
  outMsg += '

I found ' + r.options.length + ' tasks:';
  r.options.forEach((o,i)=>{ outMsg += `
${i+1}. ${o.title}${o.dueDate? ' (due '+o.dueDate+')':''}`; });
  outMsg += '
Which one did you finish? (say a number like 1)';
} else if (r.status === 'confirm_required' && r.taskId) {
  outMsg = `Mark '${r.options && r.options[0] ? r.options[0].title : r.taskTitle || 'this task'}' complete? (yes/no)`;
} else if (r.status === 'needs_clarification' && r.nextActions) {
  outMsg += '

Suggestions:
' + r.nextActions.map(a=>' - '+a).join('
');
} else if (r.status === 'error') {
  outMsg = 'There was an error: ' + outMsg + '
Try again or refine your request.';
}
return [{ structured: r, response: outMsg }];

// User reply after confirm_required status. Expect yes/no.
const txt = ($json.rawUserMessage||'').toLowerCase();
let confirmed = /^(y|yes)$/i.test(txt.trim());
return [{...$json, userConfirmed: confirmed}];

// Interpret selection index from raw user message and map to option
const txt = ($json.rawUserMessage||'').toLowerCase();
const ord = { first:1, second:2, third:3, fourth:4, fifth:5 };
let idx = null;
const m = txt.match(/\b(\d+)\b/);
if (m) idx = +m[1]; else { for (const [k,v] of Object.entries(ord)) if (txt.includes(k)) { idx = v; break; } }
const opts = $json.structured.options||[];
if (!idx || idx < 1 || idx > opts.length) {
  return [{ ...$json, selectionError: true, response: 'Please provide a valid number between 1 and '+opts.length+'.' }];
}
const chosen = opts[idx-1];
return [{ ...$json, selectionIndex: idx, chosenOption: chosen }];
